package net.civeira.phylax.common.crypto;

import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.LinkedHashMap;
import java.util.Map;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import jakarta.enterprise.context.ApplicationScoped;

/** Deterministic, versioned HMAC-SHA256 for high-entropy secrets (not passwords). */
@ApplicationScoped
public class SecretDigester {
  public static final String PREFIX = "hmac-sha256:";
  private final Map<String, String> peppers;
  private final String current;

  public SecretDigester(
      @ConfigProperty(name = "security.digest.peppers", defaultValue = "") String configured,
      @ConfigProperty(name = "security.digest.current", defaultValue = "") String current) {
    this.peppers = parse(configured);
    this.current = current.isEmpty() ? peppers.keySet().iterator().next() : current;
    if (!peppers.containsKey(this.current)) {
      throw new IllegalArgumentException("Current digest pepper is not in the key ring");
    }
  }

  private static Map<String, String> parse(String configured) {
    Map<String, String> result = new LinkedHashMap<>();
    for (String entry : configured.split(",")) {
      String[] pair = entry.trim().split(":", 2);
      if (pair.length == 2 && pair[0].matches("[a-zA-Z0-9_-]{1,32}") && !pair[1].isEmpty()) {
        result.put(pair[0], pair[1]);
      }
    }
    if (result.isEmpty()) {
      result.put("p0", "pimienta-generica");
    }
    return result;
  }

  public String digest(String plain) {
    return digestWith(current, plain);
  }

  public boolean verify(String plain, String stored) {
    String id = pepperIdOf(stored);
    return id != null && peppers.containsKey(id)
        && MessageDigest.isEqual(stored.getBytes(StandardCharsets.UTF_8),
            digestWith(id, plain).getBytes(StandardCharsets.UTF_8));
  }

  public boolean needsRehash(String stored) {
    return !current.equals(pepperIdOf(stored));
  }

  public static boolean isSupported(String stored) {
    return pepperIdOf(stored) != null;
  }

  private static String pepperIdOf(String stored) {
    if (stored == null || !stored.startsWith(PREFIX)) {
      return null;
    }
    int separator = stored.indexOf(':', PREFIX.length());
    return separator > PREFIX.length() && separator < stored.length() - 1
        ? stored.substring(PREFIX.length(), separator)
        : null;
  }

  private String digestWith(String id, String plain) {
    try {
      Mac mac = Mac.getInstance("HmacSHA256");
      mac.init(new SecretKeySpec(peppers.get(id).getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
      byte[] bytes = mac.doFinal(plain.getBytes(StandardCharsets.UTF_8));
      StringBuilder hex = new StringBuilder(bytes.length * 2);
      for (byte b : bytes) {
        hex.append(Character.forDigit((b >>> 4) & 15, 16));
        hex.append(Character.forDigit(b & 15, 16));
      }
      return PREFIX + id + ":" + hex;
    } catch (GeneralSecurityException ex) {
      throw new IllegalStateException("HMAC-SHA256 is unavailable", ex);
    }
  }
}
